 exportTransport(f.w,f.calls);f.w.studyDraft.currentOwner=()=>({kind:'magazine'});f.w.studyOutputConnection.setMagazineAdapter({read:async()=>null,onAction:async()=>{},readWorkingEdition:async()=>structuredClone(value)});f.w.ArStudyOutputHost.prepareMagazineHtml=async()=>{preparations++;await new Promise(r=>release=r);return 'prepared';};f.w.ArStudyOutputHost.downloadMagazineHtml=(...args)=>downloads.push(args);const guard=()=>{if(!valid)throw Error('Current article changed');};
