test('language-copy action submits the selected fork proof and resumes the independent child writer',async()=>{
 const f=fixture({stage:10});try{const fetch=f.w.fetch,wordsHash='a'.repeat(64);let created=null;
  f.w.fetch=async(url,options)=>{const response=await fetch(url,options),value=await response.json(),body=options?.body&&JSON.parse(options.body),q=new URL(url,f.w.location.href);const decorate=v=>{if(!v?.output)return v;const isChild=v.output.id===created,bindingId=isChild?other:child;v.wordOwner={kind:'native',bindingId,parentStudyId:'hk'};v.writingProof={kind:'native',bindingId,parentStudyId:'hk',expected:{hash:'exact-selected-fork'},rawHash:wordsHash,capturedRawHash:wordsHash};v.outputBindings=v.outputBindings.map(row=>row.outputId===v.output.id?{...row,wordOwner:v.wordOwner}:row);return v;};
   if(q.pathname==='/api/study/outputs/create'&&body?.sourceOutputId){created=body.operationId;const output=f.outputs.find(o=>o.id===created);output.language=body.targetLanguage;output.languageEdition={sourceOutputId:body.sourceOutputId,sourceWordsHash:wordsHash};value.view.output=structuredClone(output);value.view.outputs=structuredClone(f.outputs);decorate(value.view);}else if(q.pathname==='/api/study/outputs')decorate(value);return {...response,json:async()=>value};};
  let refreshes=0;f.w.workspaceNavigation={refreshOutputs:async projectId=>{refreshes++;assert.equal(projectId,'hk');assert.equal(f.w.studyOutputConnection.selection().output.id,created);return {projectId,outputs:[{id:created,rootBindingId:root}]};}};await f.w.realOutputOverview.read({projectId:'hk'});await f.w.studyOutputConnection.createLanguageEdition({projectId:'hk',outputId:'a',targetLanguage:'zh-Hans'});assert.equal(refreshes,1);
  const submitted=f.calls.find(c=>c.path==='/api/study/outputs/create').body;assert.equal(submitted.sourceOutputId,'a');assert.equal(submitted.targetLanguage,'zh-Hans');assert.equal(submitted.expectedSourceWords.bindingId,child);assert.equal(submitted.expectedSourceWords.rawHash,wordsHash);assert.equal(submitted.sourceBindingId,undefined);assert.equal(f.opens.at(-1).bindingId,other);assert.equal(f.opens.at(-1).canonicalOutputId,created);
 }finally{f.dom.window.close();}
});

test('actual language Create opens child Write and synchronizes the navigation catalog before immediate Read/Arrange',async()=>{
 let f;const modes=[],words='已保存的独立中文内容',hash='a'.repeat(64);f=fixture({stage:10,canvasMount:(w,element,options)=>{element.innerHTML='<div class="car-workspace"><button>Writing content</button><button>Read writing content</button><button>Visual content</button><main class="car-writing-page" data-writing-view="write"><textarea>'+words+'</textarea></main></div>';const owner={documentId:root,outputId:options.selectedOutputId,setView(mode){modes.push(mode);element.querySelector('main').dataset.writingView=mode;}};w.studyCompositionFocus=owner;for(const button of element.querySelectorAll('button'))button.onclick=()=>owner.setView(button.textContent==='Read writing content'?'read':button.textContent==='Writing content'?'write':'arrange');w.queueMicrotask(()=>{const host=f.hosts.at(-1);host.model.writingProof={kind:'carousel-words',projectId:'owned-physical',documentId:'owned-document',outputId:options.selectedOutputId,expected:{hash:'saved-r1'},wordsHash:hash};});return ()=>{if(w.studyCompositionFocus===owner)w.studyCompositionFocus=null;};}});
 try{const fetch=f.w.fetch;let created;
  f.w.fetch=async(url,options)=>{const response=await fetch(url,options),value=await response.json(),body=options?.body&&JSON.parse(options.body),path=new URL(url,f.w.location.href).pathname;const decorate=view=>{if(view?.output?.kind!=='carousel')return;const id=view.output.id;view.wordOwner={kind:'carousel-words',projectId:'owned-physical',documentId:'owned-document',outputId:id};view.writingProof={...view.wordOwner,expected:{hash:'saved-r1'},wordsHash:hash};view.outputBindings=view.outputBindings.map(row=>row.outputId===id?{...row,wordOwner:view.wordOwner}:row);};
   if(path==='/api/study/outputs/create'&&body?.sourceOutputId){created=body.operationId;const row=f.outputs.find(o=>o.id===created);Object.assign(row,{title:'Chinese independent copy',language:'zh-Hans',languageEdition:{sourceOutputId:'c',sourceWordsHash:hash},slides:[],caption:''});value.view.output=structuredClone(row);value.view.outputs=structuredClone(f.outputs);decorate(value.view);}else if(path==='/api/study/outputs')decorate(value);return {...response,json:async()=>value};};
  const workspace=f.w.document.querySelector('#workspace');workspace.classList.add('workspace');workspace.insertAdjacentHTML('afterbegin','<header class="topbar"><h1>Project</h1></header>');f.w.eval(fs.readFileSync(new URL('./workspace-navigation.js',import.meta.url),'utf8'));await tick();await f.w.studyOutputConnection.selectOutput({projectId:'hk',outputId:'c'});await f.w.studyOutputConnection.createLanguageEdition({projectId:'hk',outputId:'c',targetLanguage:'zh-Hans'});
  assert.equal(f.w.workspaceNavigation.selectedOutput().id,created);assert.equal(f.w.document.querySelector('[data-wn-piece]').value,created);assert.equal(f.w.document.querySelectorAll('[data-wn-piece] option').length,4);assert.equal(f.w.document.querySelector('textarea').value,words);
  const host=f.hosts.at(-1),savedOutputs=host.model.outputs;delete host.model.outputs;assert.equal(f.w.studyOutputConnection.carouselCheckSnapshot(),null,'an incomplete mounted owner cannot provide Check proof');let readDone=false;const openingRead=f.w.workspaceNavigation.changeMode('read').then(()=>{readDone=true;});await tick();assert.equal(readDone,false,'Read waits for this exact saved output model');host.model.outputs=savedOutputs;f.w.dispatchEvent(new f.w.CustomEvent('study-output-selection'));await openingRead;assert.equal(modes.at(-1),'read');assert.equal(f.w.studyOutputConnection.selection().output.id,created);assert.equal(f.w.document.querySelector('textarea').value,words);await f.w.workspaceNavigation.changeMode('arrange');assert.equal(modes.at(-1),'arrange');assert.equal(f.w.studyOutputConnection.selection().output.id,created);assert.equal(f.w.document.querySelector('textarea').value,words);
 }finally{f.dom.window.close();}
});

for(const outcome of ['ready','failed','navigated'])test('selected Article Read to Arrange shows pending owner rather than false empty while '+outcome,async()=>{
 let delayed=false,release,reject;const pending=new Promise((resolve,fail)=>{release=resolve;reject=fail;}),f=fixture({catalogGate:()=>delayed?pending:Promise.resolve()});
 try{await f.w.realOutputOverview.read({projectId:'hk'});await f.w.realOutputOverview.onAction({projectId:'hk',outputId:'c',kind:'read'});await tick();await f.w.realOutputOverview.onAction({projectId:'hk',outputId:'a',kind:'native'});await f.w.viewPhase(6);assert.equal(f.w.studyOutputConnection.selection().output.id,'a');assert.equal(f.w.studyDraft.currentBinding().id,child);delayed=true;const before=f.mounts.length;await f.w.realOutputOverview.onAction({projectId:'hk',outputId:'a',kind:'arrange'});await tick();
  const canvas=f.w.document.querySelector('#study-output-canvas');assert.match(canvas.textContent,/Opening this saved output/);assert.doesNotMatch(canvas.textContent,/No saved output|Open an owned Draft|Continue Draft/);assert.equal(f.w.document.querySelector('[data-output-create]'),null);assert.equal(f.w.studyOutputConnection.selection().rootBindingId,root);assert.equal(f.w.studyOutputConnection.selection().output.id,'a');assert.equal(f.creates,0);
  if(outcome==='failed'){reject(Error('Invented catalog unavailable'));await tick();assert.match(f.w.document.querySelector('#study-output-notice').textContent,/Invented catalog unavailable/);assert.doesNotMatch(canvas.textContent,/Opening|No saved output|Create article/);assert.match(canvas.textContent,/could not open/);assert.equal(f.w.studyOutputConnection.selection().output.id,'a');}
  else if(outcome==='navigated'){await f.w.switchProject('ref-an-cha');release();await tick();assert.equal(f.project.id,'ref-an-cha');assert.ok(f.mounts.slice(before).every(m=>m.scope.parentStudyId==='ref-an-cha'&&m.scope.rootBindingId===other));assert.doesNotMatch(f.w.document.body.textContent,/Invented catalog unavailable/);}
  else{release();await tick();assert.equal(f.mounts.length,before+1);assert.equal(f.mounts.at(-1).scope.rootBindingId,root);assert.equal(f.mounts.at(-1).selectedOutputId,'a');assert.doesNotMatch(canvas.textContent,/Opening|No saved output/);}
  assert.equal(f.creates,0);assert.equal(f.calls.some(c=>c.path==='/api/study/photos/select'),false);
 }finally{release();await tick();f.dom.window.close();}
});
